# ==========================================================================
# 2. Core simulator class — no I/O, safe to reuse behind a web API
# ==========================================================================

@dataclass
class Patient:
    ward: str
    disease: str
    name: str
    age: int
    gender: str
    symptoms: str
    history: str
    medications: str
    vitals: dict


def _generate_name_and_gender() -> tuple[str, str]:
    """Return a freshly generated (name, gender) pair each call."""
    gender = random.choice(["Male", "Female"])
    if _FAKER_AVAILABLE:
        name = _fake.name_male() if gender == "Male" else _fake.name_female()
    else:
        pool = _FALLBACK_MALE_NAMES if gender == "Male" else _FALLBACK_FEMALE_NAMES
        # Combine a random first + random last name from the pool's parts so
        # repeated sessions don't quickly repeat the exact same person.
        first = random.choice(pool).split()[0]
        last = random.choice(pool).split()[-1]
        name = f"{first} {last}"
    return name, gender


def _generate_vitals(vitals_ranges: dict) -> dict:
    bp_sys = random.randint(*vitals_ranges["BP_sys"])
    bp_dia = random.randint(*vitals_ranges["BP_dia"])
    hr = random.randint(*vitals_ranges["HR"])
    temp = round(random.uniform(*vitals_ranges["Temp"]), 1)
    spo2 = random.randint(*vitals_ranges["SpO2"])
    return {"BP": f"{bp_sys}/{bp_dia}", "HR": str(hr), "Temp": f"{temp}C", "SpO2": f"{spo2}%"}


def generate_patient(ward_name: str) -> Patient:
    """Randomly assemble a brand-new patient for `ward_name`. Called fresh
    every session — never reads from a fixed list of pre-made profiles."""
    if ward_name not in WARDS:
        raise ValueError(f"Unknown ward: {ward_name}")

    disease = random.choice(WARDS[ward_name]["diseases"])
    name, gender = _generate_name_and_gender()
    age = random.randint(*disease["age_range"])

    n_symptoms = random.randint(2, min(3, len(disease["symptom_pool"])))
    n_history = random.randint(1, min(2, len(disease["history_pool"])))
    n_meds = random.randint(0, min(2, len(disease["medication_pool"])))

    symptoms = ", ".join(random.sample(disease["symptom_pool"], n_symptoms))
    history = ", ".join(random.sample(disease["history_pool"], n_history))
    meds_sample = random.sample(disease["medication_pool"], n_meds) if n_meds else []
    medications = ", ".join(meds_sample) if meds_sample else "None currently"

    vitals = _generate_vitals(disease["vitals_ranges"])

    return Patient(
        ward=ward_name,
        disease=disease["name"],
        name=name,
        age=age,
        gender=gender,
        symptoms=symptoms,
        history=history,
        medications=medications,
        vitals=vitals,
    )


@dataclass
class PatientSimulator:
    """Holds one active patient session and answers doctor questions."""

    patient: Optional[Patient] = None
    conversation: list = field(default_factory=list)  # [(question, answer), ...]
    _client: Optional["object"] = None
    _model_name: str = _DEFAULT_GEMINI_MODEL

    def __post_init__(self) -> None:
        api_key = (
            os.environ.get("GEMINI_API_KEY")
            or os.environ.get("GOOGLE_API_KEY")
            or _HARDCODED_GEMINI_API_KEY
        )
        self._model_name = os.environ.get("GEMINI_MODEL", _DEFAULT_GEMINI_MODEL)
        if _GEMINI_AVAILABLE and api_key:
            try:
                self._client = _genai_sdk.Client(api_key=api_key)
            except Exception:
                self._client = None

    # -- session setup ----------------------------------------------------

    def list_wards(self) -> list:
        return list(WARDS.keys())

    def start_session(self, ward_name: str) -> Patient:
        """Generate a brand-new patient for `ward_name` and start a session."""
        self.patient = generate_patient(ward_name)
        self.conversation = []
        return self.patient

    # -- Q&A ----------------------------------------------------------------

    def ask(self, question: str, api_key: Optional[str] = None) -> str:
        """Return the patient's natural answer to `question`."""
        if self.patient is None:
            raise RuntimeError("No active patient session. Call start_session() first.")

        # Dynamically initialize or update client if an API key is provided
        effective_key = (
            api_key
            or os.environ.get("GEMINI_API_KEY")
            or os.environ.get("GOOGLE_API_KEY")
            or _HARDCODED_GEMINI_API_KEY
        )
        if _GEMINI_AVAILABLE and effective_key and (self._client is None or api_key):
            try:
                self._client = _genai_sdk.Client(api_key=effective_key)
            except Exception:
                pass

        if self._client is not None:
            answer = self._ask_llm(question)
        else:
            answer = self._ask_fallback(question)

        self.conversation.append((question, answer))
        return answer

    def _system_prompt(self) -> str:
        p = self.patient
        return textwrap.dedent(f"""
            You are role-playing as a patient in a medical training simulator.
            You are {p.name}, a {p.age}-year-old {p.gender}.
            You have been diagnosed (unknown to you, the doctor is diagnosing you) with: {p.disease}.
            Your symptoms: {p.symptoms}.
            Relevant medical history: {p.history}.
            Current medications: {p.medications}.
            Vital signs (only reveal if asked directly): {p.vitals}.

            Rules:
            - Always answer in the FIRST PERSON as the patient.
            - Answer naturally in 1 to 3 realistic sentences. Express your pain, feelings, and concern as a patient speaking to a physician.
            - Stay strictly consistent with your symptoms ({p.symptoms}) and medical history ({p.history}).
            - Use plain layperson language. Do not state your medical diagnosis name unless the doctor already diagnosed you.
            - If asked something unrelated to your case, answer briefly and naturally.
        """).strip()

    def _call_gemini_sync(self, question: str):
        """The actual blocking network call — run inside a worker thread so
        the caller can enforce a hard timeout on it."""
        config = _genai_types.GenerateContentConfig(
            system_instruction=self._system_prompt(),
            temperature=0.7,
            max_output_tokens=300,
        )
        
        # Deduplicated list of models to try
        candidate_models = []
        for m in [self._model_name, "gemini-3.5-flash-lite", "gemini-3.5-flash", "gemini-3.7-flash", "gemini-3.6-flash"]:
            if m and m not in candidate_models:
                candidate_models.append(m)

        last_error = None
        for m in candidate_models:
            try:
                return self._client.models.generate_content(
                    model=m,
                    contents=question,
                    config=config,
                )
            except Exception as e:
                last_error = e
                continue

        if last_error:
            raise last_error

    def _ask_llm(self, question: str) -> str:
        max_attempts = 3
        base_delay = 1.5
        request_timeout = 15

        for attempt in range(1, max_attempts + 1):
            reason = None
            is_transient = False
            try:
                future = _LLM_EXECUTOR.submit(self._call_gemini_sync, question)
                resp = future.result(timeout=request_timeout)
                text = (resp.text or "").strip()
                return text if text else self._ask_fallback(question)
            except concurrent.futures.TimeoutError:
                reason = f"no response after {request_timeout}s"
                is_transient = True
            except Exception as exc:
                reason = str(exc)
                is_transient = any(code in reason for code in ("503", "UNAVAILABLE", "429", "RESOURCE_EXHAUSTED"))

            if is_transient and attempt < max_attempts:
                delay = base_delay * (2 ** (attempt - 1))
                time.sleep(delay)
                continue
            return self._ask_fallback(question)

    # -- offline fallback responder ---------------------------------------

    def _ask_fallback(self, question: str) -> str:
        p = self.patient
        q = question.lower()

        if any(w in q for w in ["how are you", "how do you feel", "feeling", "what brings"]):
            return f"Honestly doctor, I'm feeling quite unwell. I've been experiencing severe {p.symptoms.lower()}, and it's making me really concerned."
        if any(w in q for w in ["pain", "hurt", "ache", "discomfort", "symptom"]):
            return f"Yes doctor, it started recently as a very uncomfortable {p.symptoms.split(',')[0].lower()}. It gets worse when I move around."
        if any(w in q for w in ["history", "before", "past", "previous", "prior"]):
            return f"Well, in my medical past I've dealt with {p.history.lower()}. Otherwise I try to take care of myself."
        if any(w in q for w in ["medication", "medicine", "drug", "pill", "taking"]):
            return f"I am currently taking {p.medications.lower()} as prescribed by my doctor."
        if any(w in q for w in ["age", "old"]):
            return f"I'm {p.age} years old."
        if any(w in q for w in ["smoke", "smoking", "alcohol", "drink", "lifestyle"]):
            return f"Regarding my habits, {p.history.lower()}."
        if any(w in q for w in ["vital", "blood pressure", "heart rate", "temperature", "oxygen"]):
            v = p.vitals
            return f"My latest vital check showed blood pressure of {v['BP']}, heart rate of {v['HR']} BPM, temperature of {v['Temp']}, and oxygen at {v['SpO2']}."
        if any(w in q for w in ["name", "who are you"]):
            return f"My name is {p.name}, doctor."
        if any(w in q for w in ["when", "start", "long", "onset", "time"]):
            return "It started a couple of days ago very suddenly, and it's been progressively getting worse since yesterday."
        return f"Mainly it's the {p.symptoms.split(',')[0].lower()} that's bothering me the most right now, doctor."
        if "when" in q and "start" in q:
            return "It started a couple of days ago and has been getting worse since."
        # generic catch-all, still grounded in the case
        return f"It's mainly the {p.symptoms.split(',')[0].lower()} that's bothering me most right now."


# ==========================================================================
# 3. CLI front-end
# ==========================================================================

def _print_header(text: str) -> None:
    print("\n" + "=" * 60)
    print(text)
    print("=" * 60)


def choose_ward(sim: PatientSimulator) -> str:
    wards = sim.list_wards()
    _print_header("Select a Ward")
    for i, w in enumerate(wards, start=1):
        print(f"  {i}. {w}")

    while True:
        raw = input("\nEnter a number or ward name: ").strip()
        if raw.isdigit() and 1 <= int(raw) <= len(wards):
            return wards[int(raw) - 1]
        for w in wards:
            if raw.lower() == w.lower():
                return w
        print("Invalid choice — please enter a valid number or ward name from the list.")


def print_patient_details(patient: Patient) -> None:
    _print_header("New Patient (freshly generated)")
    print(f"  Name:            {patient.name}")
    print(f"  Age / Gender:    {patient.age} / {patient.gender}")
    print(f"  Presenting with: {patient.symptoms}")
    print(f"  Medical history: {patient.history}")
    print(f"  Medications:     {patient.medications}")
    print(f"  Vitals:          " + ", ".join(f"{k}: {v}" for k, v in patient.vitals.items()))
    print("\n  Type your questions to the patient below. Type 'end' to finish the case.")


def run_cli() -> None:
    sim = PatientSimulator()

    if sim._client is None:
        print("[info] No Gemini API key found (or `google-genai` not installed) — "
              "running with the built-in offline responder.\n"
              "       Get a free key at https://aistudio.google.com/apikey, then:\n"
              "         pip install google-genai\n"
              "         export GEMINI_API_KEY=your_key_here")
    else:
        print(f"[info] Using Gemini model: {sim._model_name}")
    if not _FAKER_AVAILABLE:
        print("[info] Faker not installed — using a small built-in name pool instead (`pip install faker` for more variety).")

    ward = choose_ward(sim)
    patient = sim.start_session(ward)
    print_patient_details(patient)

    _print_header(f"Consultation — {patient.name} ({sim.patient.disease}) [hidden from doctor]")
    print("(The diagnosis above is hidden from you in a real exercise; shown here for demo purposes.)")

    while True:
        question = input("\nDoctor: ").strip()
        if not question:
            continue
        if question.strip().lower() == "end":
            print(f"\nPatient: Thank you, doctor. Goodbye and take care!")
            break
        answer = sim.ask(question)
        print(f"Patient: {answer}")


if __name__ == "__main__":
    try:
        run_cli()
    except (KeyboardInterrupt, EOFError):
        print("\n\nSession ended.")


